mapper.select:
select
,r.origin_name,s.business_name
from whitelisted_credit_cards mt left join white_upload_record r on mt.white_upload_id = r.id
    left join shop s on mt.shop_id = s.id

    and mt.id = #{id}
    and mt.full_number = #{fullNumber}
    and mt.card_finger = #{cardFinger}
    and mt.bin_number = #{binNumber}
    and mt.last_four_number = #{lastFourNumber}
    and mt.email = #{email}

    and mt.created_at >= #{createdAt} and mt.created_at <
        DATE_ADD(#{createdAt}, INTERVAL 1 DAY)

    and mt.created_by = #{createdBy}
    and mt.remark = #{remark}
    and s.id = #{shopId}
    and r.origin_name LIKE CONCAT('%', #{originName}, '%')
    and s.business_name =#{businessName}
    and mt.risk_level = #{riskLevel}

order by mt.updated_at desc, mt.created_by desc

mapper.update:
update whitelisted_credit_cards
full_number = #{fullNumber}, bin_number = #{binNumber}, last_four_number = #{lastFourNumber}, email = #{email}, created_at = #{createdAt}, created_by = #{createdBy}, remark = #{remark},
where id = #{id}
